export function statementEmblem(x,y,width,monochrome=false) {
  return `<g aria-hidden="true" transform="translate(${x+width/10} ${y}) scale(${width/400})">${monochrome?inkEmblem:colorEmblem}</g>`;
}
function arcText(text,radius,start,end) {
  const chars=[...text],count=chars.length;
  return chars.map((char,index)=>{
    const angle=start+(end-start)*(index+.5)/count,radians=angle*Math.PI/180;
    const rotation=angle+(end>start?90:-90);
    return `<text x="0" y="0" text-anchor="middle" font-size="14" font-weight="700" transform="translate(${(Math.cos(radians)*radius).toFixed(3)} ${(Math.sin(radians)*radius).toFixed(3)}) rotate(${rotation.toFixed(3)})">${char}</text>`;
  }).join('');
}
